create table public.music_compositions (id uuid primary key default gen_random_uuid(), student_id uuid references public.profiles(id) on delete set null, activity_id uuid references public.activities(id) on delete set null, project_submission_id uuid, title text not null, tempo_bpm numeric(6,2) not null default 80 check (tempo_bpm > 0), beats_per_measure smallint not null default 4 check (beats_per_measure > 0), beat_unit smallint not null default 4 check (beat_unit > 0), total_beats numeric(10,4) check (total_beats is null or total_beats >= 0), metadata jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());;
